insert into public.posttest_questions (topic_key, question, options, correct_index, explanation) values
('phishing', 'Recibes un correo de ''SUNAT'' pidiendo actualizar tu clave SOL con un enlace adjunto. ¿Qué haces?', '["Hacer clic de inmediato para evitar una multa","No hacer clic; verificar directamente en el portal oficial de SUNAT","Reenviarlo a contabilidad para que lo revisen ellos","Responder pidiendo más información"]'::jsonb, 1, 'SUNAT no solicita actualizar claves por correo con enlaces. Verifica siempre entrando manualmente al portal oficial.'),
('phishing', 'Un proveedor habitual te escribe desde un correo ligeramente distinto al de siempre pidiendo cambiar la cuenta bancaria para el próximo pago. ¿Qué haces?', '["Actualizar el dato de inmediato porque es un proveedor conocido","Confirmar por teléfono con un número ya registrado antes de cambiar nada","Ignorar el correo sin avisar al proveedor","Pedir el cambio por escrito en el mismo correo"]'::jsonb, 1, 'El fraude del ''proveedor comprometido'' cambia cuentas bancarias vía correo. Siempre se valida por un canal alterno y conocido.'),
('phishing', '¿Cuál de estas URLs es más probable que sea phishing dirigido a un banco peruano?', '["www.bcp.com.pe","www.bcp-verificacion-cliente.com","www.viabcp.com","www.bcp.gob.pe"]'::jsonb, 1, 'Los dominios largos con palabras añadidas (''verificacion-cliente'') y extensión distinta suelen ser señal de phishing.'),
('phishing', 'Un correo de phishing suele generar sensación de:', '["Urgencia y miedo a perder algo","Tranquilidad y confianza total","Aburrimiento","Indiferencia"]'::jsonb, 0, 'Los atacantes usan urgencia (''tu cuenta será bloqueada en 24h'') para que la víctima actúe sin pensar.'),
('phishing', 'Recibes un mensaje de WhatsApp de un ''número de soporte de tu banco'' pidiendo el código OTP que te llegó por SMS. ¿Qué haces?', '["Enviar el código porque dice ser del banco","Nunca compartir el código OTP con nadie, ni siquiera ''el banco''","Enviarlo solo si te llaman por teléfono también","Pedir que te llamen primero antes de dar el código"]'::jsonb, 1, 'Ningún banco pide el código OTP por WhatsApp o llamada. Compartirlo permite al atacante completar una transacción fraudulenta.'),
('phishing', '¿Qué es el ''smishing''?', '["Phishing realizado por mensajes de texto SMS","Un virus que ataca impresoras","Un tipo de firewall","Un método de cifrado de discos"]'::jsonb, 0, 'Smishing es phishing vía SMS, muy usado para simular alertas bancarias o de encomiendas con enlaces maliciosos.'),
('phishing', 'Un correo de phishing incluye un archivo adjunto llamado ''Factura_2025.zip''. ¿Qué es lo correcto?', '["Abrirlo porque parece una factura legítima","No abrirlo si no esperabas ese archivo; verificar con el remitente por otro canal","Reenviarlo a otros para pedir opinión","Cambiarle el nombre y luego abrirlo"]'::jsonb, 1, 'Archivos comprimidos inesperados son un vector común de malware. Verifica con el remitente antes de abrir cualquier adjunto no solicitado.'),
('phishing', '¿Qué es el ''vishing''?', '["Phishing por llamada telefónica","Un tipo de antivirus","Un protocolo de red segura","Un método de respaldo en la nube"]'::jsonb, 0, 'Vishing es phishing por voz/llamada telefónica, donde el atacante se hace pasar por banco, soporte técnico o entidad oficial.'),
('phishing', 'Al pasar el cursor sobre un enlace de un correo sospechoso (sin hacer clic), ¿qué deberías revisar?', '["El color del texto del enlace","La URL real que aparece en la parte inferior del navegador o cliente de correo","El tamaño de la fuente","Si el correo tiene imágenes"]'::jsonb, 1, 'Pasar el cursor revela la URL de destino real, que puede diferir del texto visible del enlace y delatar el fraude.'),
('phishing', 'Un empleado recibe un correo urgente ''del gerente general'' pidiendo comprar tarjetas de regalo y enviar los códigos. ¿Qué debe hacer?', '["Comprarlas de inmediato para no quedar mal","Verificar la solicitud por un canal distinto (llamada o en persona) antes de actuar","Responder pidiendo el monto exacto por correo","Consultar a un compañero de otro área"]'::jsonb, 1, 'El fraude del CEO (BEC) usa urgencia y autoridad falsa. Toda solicitud inusual de pago debe verificarse por un canal alterno.'),
('phishing', '¿Cuál de estas es una buena práctica ante un correo sospechoso de phishing?', '["Reportarlo al área de TI o al administrador de la plataforma","Reenviarlo a todos los compañeros para alertarlos","Contestar preguntando quién lo envió","Guardarlo para revisarlo después"]'::jsonb, 0, 'Reportar al área responsable permite bloquear el remitente y alertar a toda la organización de forma controlada.'),
('phishing', 'Un cliente dice haber recibido un correo ''de tu empresa'' pidiendo depositar en una nueva cuenta. Tu empresa no envió eso. ¿Qué es esto?', '["Un caso de suplantación de identidad (phishing) usando el nombre de tu empresa","Un error de tipeo del cliente","Una promoción interna","Un problema de correo no relacionado a seguridad"]'::jsonb, 0, 'Los atacantes suplantan marcas conocidas para engañar a los clientes de esa empresa y desviar pagos a cuentas fraudulentas.'),
('phishing', '¿Qué hace más difícil detectar el phishing hoy en día respecto a hace unos años?', '["Que los textos ahora tienen más errores ortográficos","El uso de IA generativa para redactar mensajes muy convincentes y sin errores","Que los atacantes ya no usan correo electrónico","Que los bancos publican sus contraseñas"]'::jsonb, 1, 'La IA generativa permite redactar correos de phishing sin errores gramaticales, quitando una señal clásica de alerta.'),
('phishing', 'Un enlace acortado (bit.ly, tinyurl) llega en un correo no solicitado. ¿Qué riesgo tiene?', '["Ninguno, los enlaces acortados son siempre seguros","Oculta la URL real de destino, dificultando detectar si es phishing","Solo funciona en celulares","Solo lo pueden crear empresas verificadas"]'::jsonb, 1, 'Los acortadores ocultan el dominio real, siendo usados frecuentemente para disfrazar enlaces maliciosos.'),
('phishing', '¿Qué es el ''spear phishing''?', '["Phishing masivo sin objetivo específico","Phishing dirigido y personalizado a una persona u organización específica","Un antivirus especializado","Un tipo de cifrado de correo"]'::jsonb, 1, 'El spear phishing investiga a la víctima (cargo, contactos, rutina) para hacer el engaño mucho más creíble y difícil de detectar.'),
('phishing', 'Recibes un correo del ''área de RRHH'' pidiendo tus datos bancarios para un supuesto bono. No esperabas ningún bono. ¿Qué haces?', '["Enviar los datos porque es un beneficio","Confirmar directamente con RRHH por un canal interno conocido antes de responder","Reenviarlo a un familiar para pedir consejo","Ignorarlo sin reportarlo"]'::jsonb, 1, 'Cualquier solicitud de datos bancarios no esperada debe confirmarse por un canal interno oficial, nunca respondiendo directo al correo.'),
('phishing', '¿Cuál es la mejor defensa técnica adicional contra el phishing en el correo corporativo?', '["Activar la autenticación en dos pasos (2FA) en las cuentas de correo","Compartir la contraseña del correo entre varios empleados","Desactivar el antivirus para no generar falsos positivos","Usar la misma contraseña del correo en todos los sistemas"]'::jsonb, 0, 'El 2FA evita que un atacante entre a la cuenta aunque haya robado la contraseña mediante phishing.'),
('phishing', 'Un mensaje de texto dice: ''Tu paquete de Olva Courier está retenido, paga S/2 aquí: [enlace]''. ¿Qué es esto probablemente?', '["Un cobro legítimo de la empresa de courier","Un caso de smishing simulando una empresa de encomiendas","Una promoción oficial","Un mensaje de tu banco"]'::jsonb, 1, 'Es común el smishing usando el nombre de couriers conocidos para robar datos de tarjeta con pagos falsos de bajo monto.'),
('phishing', '¿Qué debes verificar SIEMPRE antes de introducir tu contraseña en una página a la que llegaste por un enlace de correo?', '["Que la página tenga los mismos colores que la original","Que el dominio en la barra de direcciones sea exactamente el oficial","Que cargue rápido","Que tenga muchas imágenes"]'::jsonb, 1, 'El dominio exacto en la barra de direcciones es la única verificación confiable; el diseño se puede clonar fácilmente.'),
('phishing', 'Un correo de phishing pide ''confirmar tu contraseña actual'' para ''mantener la seguridad de tu cuenta''. ¿Qué principio se viola aquí?', '["Ninguna empresa legítima pide tu contraseña por correo","Es una práctica normal de seguridad","Solo lo hacen bancos internacionales","Es válido si el correo tiene el logo correcto"]'::jsonb, 0, 'Ninguna plataforma legítima solicita tu contraseña por correo; hacerlo es siempre señal de phishing.'),
('phishing', '¿Qué es el ''pretexting'' en ingeniería social?', '["Crear una historia falsa creíble para obtener información o acceso","Un tipo de cifrado de mensajes","Un antivirus gratuito","Un protocolo de red"]'::jsonb, 0, 'El pretexting inventa un escenario convincente (ej. ''soy del área de TI'') para manipular a la víctima y obtener datos o acceso.'),
('phishing', 'Un desconocido llama diciendo ser ''técnico de soporte de Microsoft'' y pide acceso remoto a tu PC de trabajo. ¿Qué haces?', '["Dar acceso porque menciona una empresa conocida","Negar el acceso y colgar; Microsoft no llama de forma no solicitada","Pedirle que se identifique con su DNI por teléfono","Dar acceso solo si suena convincente"]'::jsonb, 1, 'Las empresas de software no llaman de forma no solicitada ofreciendo soporte remoto; es una táctica común de fraude.'),
('phishing', '¿Cuál de estas señales en un correo indica posible phishing?', '["El remitente coincide exactamente con el dominio oficial de la empresa","Pide hacer clic urgente en un enlace para ''evitar la suspensión de la cuenta''","No tiene ningún enlace ni adjunto","Fue enviado en horario laboral"]'::jsonb, 1, 'La urgencia combinada con un enlace para ''evitar consecuencias'' es un patrón clásico de phishing.'),
('phishing', 'Si ya hiciste clic accidentalmente en un enlace de phishing pero no ingresaste datos, ¿qué debes hacer?', '["No hacer nada porque no pasó nada","Reportarlo a TI/administrador y cambiar contraseñas por precaución","Borrar el historial del navegador únicamente","Reiniciar la PC y olvidarlo"]'::jsonb, 1, 'Aunque no se ingresaron datos, reportar el incidente permite bloquear el dominio y revisar si hubo descarga de malware.'),
('phishing', '¿Por qué el phishing sigue siendo la puerta de entrada más común para ataques a MYPES?', '["Porque las MYPES no usan correo electrónico","Porque explota errores humanos, que son más fáciles de aprovechar que fallas técnicas","Porque los ataques técnicos ya no existen","Porque solo afecta a empresas grandes"]'::jsonb, 1, 'El phishing ataca al factor humano, evitando la necesidad de vulnerar sistemas técnicos protegidos, por eso sigue siendo tan efectivo.'),
('ia_amenazas', '¿Qué característica hace peligroso un ataque de voz clonada con IA en el entorno laboral?', '["Que suena exactamente igual a la persona real, generando confianza inmediata","Que solo funciona en videollamadas","Que requiere acceso físico al celular de la víctima","Que solo la usan gobiernos"]'::jsonb, 0, 'La clonación de voz con IA puede sonar idéntica a un directivo real, por lo que genera confianza y reduce la sospecha de fraude.'),
('ia_amenazas', 'Recibes un video donde el ''dueño de la empresa'' pide una transferencia urgente. Algo se ve poco natural en sus parpadeos. ¿Qué podría ser?', '["Un problema de conexión a internet","Un posible deepfake generado con IA","Un efecto de cámara normal","Una broma sin importancia"]'::jsonb, 1, 'Parpadeos poco naturales, iluminación inconsistente o movimientos rígidos son señales típicas de un video deepfake.'),
('ia_amenazas', '¿Qué medida ayuda a mitigar fraudes por voz/video clonado con IA en decisiones financieras?', '["Establecer una palabra clave o segundo canal de verificación para transferencias grandes","Confiar siempre en llamadas de números conocidos","Aumentar el volumen de la llamada","Grabar la llamada para usarla después"]'::jsonb, 0, 'Una palabra clave acordada previamente o verificación por un segundo canal evita que una voz/video clonado autorice pagos fraudulentos.'),
('ia_amenazas', '¿Qué es un chatbot malicioso usado en ingeniería social con IA?', '["Un asistente que simula ser soporte técnico o de ventas para robar datos o dinero","Un antivirus basado en inteligencia artificial","Un sistema de respaldo automático","Un firewall de nueva generación"]'::jsonb, 0, 'Los atacantes usan chatbots con IA para sostener conversaciones convincentes y extraer datos personales o financieros de las víctimas.'),
('ia_amenazas', 'Un correo generado con IA no tiene errores ortográficos ni de redacción. ¿Qué implica esto para detectar phishing?', '["Que ya no hay riesgo de phishing","Que la falta de errores ya no es un indicador confiable de un correo legítimo","Que solo los bancos pueden usar IA","Que el correo es automáticamente seguro"]'::jsonb, 1, 'La IA generativa redacta textos perfectos, por lo que ya no basta con revisar ortografía para distinguir un correo legítimo de uno falso.'),
('ia_amenazas', '¿Qué es el ''prompt injection'' en el contexto de asistentes de IA usados por una empresa?', '["Una técnica para manipular las instrucciones de un modelo de IA y hacer que revele información o actúe fuera de su función","Un tipo de vacuna informática","Un método de respaldo de datos","Una forma de acelerar el internet"]'::jsonb, 0, 'El prompt injection intenta engañar a un asistente de IA con instrucciones ocultas para que ignore sus reglas y filtre datos o realice acciones no autorizadas.'),
('ia_amenazas', 'Un empleado sube datos confidenciales de clientes a un chatbot de IA público para ''resumir un reporte''. ¿Qué riesgo existe?', '["Ninguno, los chatbots de IA son totalmente privados","Los datos podrían quedar almacenados o usados para entrenar el modelo, filtrando información sensible","El chatbot rechazará automáticamente los datos","Solo es riesgo si el archivo es una imagen"]'::jsonb, 1, 'Muchas herramientas de IA pública pueden almacenar o reutilizar los datos ingresados; información sensible no debe subirse sin verificar la política de privacidad.'),
('ia_amenazas', '¿Cuál es una buena política interna frente al uso de IA generativa por empleados?', '["Prohibir cualquier uso de tecnología nueva sin excepción","Definir qué tipo de información NO puede compartirse con herramientas de IA externas","Permitir subir cualquier dato porque la IA es confiable","No es necesario ningún control"]'::jsonb, 1, 'Establecer lineamientos claros sobre qué datos no deben ingresarse a IA pública reduce el riesgo de fuga de información.'),
('ia_amenazas', '¿Qué es un ''deepfake de audio'' usado para fraude en MYPES?', '["Una grabación real sin editar","Audio sintético generado con IA que imita la voz de una persona real","Un tipo de música de fondo en llamadas","Un sistema de traducción automática"]'::jsonb, 1, 'El deepfake de audio clona voces reales con pocos segundos de muestra, usado para suplantar a jefes o proveedores en llamadas fraudulentas.'),
('ia_amenazas', 'Un atacante usa IA para generar cientos de perfiles falsos de LinkedIn que contactan a tus empleados. ¿Qué busca lograr?', '["Vender productos legítimos","Ganar confianza para luego robar información o credenciales (ingeniería social a escala)","Mejorar la reputación de la empresa","Ninguna de las anteriores"]'::jsonb, 1, 'Perfiles falsos generados con IA permiten ingeniería social masiva y personalizada, buscando credenciales o información interna.'),
('ia_amenazas', '¿Por qué la IA ha reducido la barrera de entrada para el cibercrimen?', '["Porque permite generar malware, correos de phishing y voces falsas sin necesidad de expertise técnico avanzado","Porque la IA solo la usan expertos certificados","Porque las leyes ya prohibieron su mal uso globalmente","Porque no puede automatizar ningún ataque"]'::jsonb, 0, 'Herramientas de IA accesibles permiten a atacantes con poco conocimiento técnico crear ataques sofisticados de phishing, malware o suplantación.'),
('ia_amenazas', 'Ante una llamada con voz clonada pidiendo una acción urgente, ¿cuál es la mejor primera reacción?', '["Actuar de inmediato para no fallar a la persona","Colgar y verificar por un canal alterno ya conocido (no el mismo número que llamó)","Pedir que repita la solicitud dos veces","Grabar la llamada y continuar"]'::jsonb, 1, 'Verificar por un canal alterno y ya conocido rompe el control del atacante sobre la comunicación y confirma la autenticidad real.'),
('ia_amenazas', '¿Qué es el ''malware polimórfico'' potenciado con IA?', '["Software malicioso que cambia su código automáticamente para evadir la detección de antivirus","Un antivirus que se actualiza solo","Un tipo de respaldo en la nube","Un protocolo de red segura"]'::jsonb, 0, 'La IA permite generar variantes de malware que cambian constantemente su firma digital, dificultando su detección por antivirus tradicionales.'),
('ia_amenazas', 'Un video viral muestra a una autoridad peruana anunciando algo que nunca dijo. ¿Qué riesgo representa para tu empresa si circula algo similar sobre tu marca?', '["Ninguno, los videos falsos no afectan negocios","Daño reputacional y posible fraude usando la imagen de la empresa (deepfake corporativo)","Solo afecta a figuras públicas, no a empresas","Mejora la visibilidad de la marca"]'::jsonb, 1, 'Los deepfakes corporativos pueden dañar la reputación de una MYPE o ser usados para engañar a sus propios clientes.'),
('ia_amenazas', '¿Qué recomendación es válida al recibir instrucciones de un ''directivo'' por un canal inusual (ej. WhatsApp personal en vez del sistema oficial)?', '["Ejecutar la instrucción de inmediato por respeto a la jerarquía","Sospechar y verificar por el canal formal habitual antes de actuar","Ignorar completamente sin verificar","Reenviar el mensaje a toda la empresa"]'::jsonb, 1, 'Un canal inusual para una instrucción importante es señal de alerta; se debe verificar por el canal formal antes de ejecutar cualquier acción.'),
('ia_amenazas', '¿Qué es un ''agente autónomo de IA'' malicioso en ciberseguridad?', '["Un programa que usa IA para ejecutar ataques de forma automática, como buscar vulnerabilidades o enviar phishing a gran escala","Un antivirus con inteligencia artificial","Un chatbot de atención al cliente","Un sistema de facturación electrónica"]'::jsonb, 0, 'Los agentes autónomos maliciosos pueden automatizar el reconocimiento de objetivos, generación de phishing y explotación de vulnerabilidades sin intervención humana constante.'),
('ia_amenazas', '¿Cómo puede un atacante usar IA para investigar a un empleado antes de un ataque de spear phishing?', '["Analizando redes sociales públicas para personalizar el mensaje de forma creíble","La IA no puede analizar información pública","Solo puede usar datos internos de la empresa","No existe forma de automatizar esta investigación"]'::jsonb, 0, 'La IA puede procesar rápidamente información pública (redes sociales, noticias) para crear mensajes de phishing muy personalizados y creíbles.'),
('ia_amenazas', '¿Qué precaución deben tomar los empleados al usar asistentes de IA para redactar correos con clientes?', '["Ninguna, la IA nunca comete errores","Revisar que no se incluyan datos confidenciales de otros clientes en el prompt ni en la respuesta generada","Copiar y pegar la respuesta sin revisión","Usar siempre el mismo prompt para todos los clientes"]'::jsonb, 1, 'Es necesario revisar que el uso de IA no filtre datos confidenciales de terceros dentro del contenido generado.'),
('ia_amenazas', 'Una nota de voz de WhatsApp ''de tu jefe'' suena ligeramente robótica en ciertas palabras. ¿Qué deberías sospechar?', '["Que el jefe está resfriado","Que podría ser un audio generado o alterado con IA","Que el celular tiene mala señal solamente","No hay nada que sospechar"]'::jsonb, 1, 'Artefactos o inconsistencias en el tono pueden ser señal de una voz clonada con IA, especialmente si pide una acción urgente.'),
('ia_amenazas', '¿Qué es el ''deepfake en tiempo real'' usado en videollamadas fraudulentas?', '["Tecnología que modifica el rostro y voz de una persona en vivo durante una videollamada para suplantar su identidad","Un filtro de belleza de redes sociales","Un sistema de traducción simultánea","Una función de zoom digital"]'::jsonb, 0, 'Existen herramientas que permiten falsificar rostro y voz en videollamadas en vivo, usadas para suplantar directivos en fraudes corporativos.'),
('ia_amenazas', '¿Por qué es riesgoso confiar únicamente en la videollamada como método de verificación de identidad hoy en día?', '["Porque las videollamadas nunca fallan técnicamente","Porque la tecnología deepfake en vivo puede suplantar rostro y voz de forma convincente","Porque las videollamadas ya no se usan","Porque no es un riesgo real"]'::jsonb, 1, 'La tecnología deepfake en tiempo real hace que la videollamada por sí sola ya no sea prueba suficiente de identidad en decisiones críticas.'),
('ia_amenazas', 'Un correo de phishing generado con IA incluye detalles reales de un proyecto interno de tu empresa. ¿Cómo pudo obtenerlos el atacante?', '["Es imposible, siempre son datos inventados","Pudo recopilarlos de filtraciones previas, redes sociales o ingeniería social combinada con IA","Los correos de phishing nunca contienen datos reales","Solo empleados internos pueden generar ese contenido"]'::jsonb, 1, 'Los atacantes combinan datos filtrados o públicos con IA generativa para crear phishing altamente convincente y específico.'),
('ia_amenazas', '¿Qué rol cumple la capacitación constante del personal frente a amenazas de IA que evolucionan rápido?', '["Ninguno, la tecnología avanza más rápido que cualquier capacitación","Es clave, ya que mantiene actualizado el criterio humano ante nuevas tácticas de fraude","Solo sirve para el área de sistemas","Es un gasto innecesario"]'::jsonb, 1, 'Dado que las amenazas con IA evolucionan rápido, la capacitación continua mantiene al personal alerta ante nuevas variantes de fraude.'),
('ia_amenazas', '¿Qué se recomienda hacer si un asistente de IA de la empresa responde de forma extraña tras recibir un mensaje con instrucciones ocultas de un usuario?', '["Ignorarlo, es normal","Reportarlo como posible intento de prompt injection y revisar los registros de uso","Reiniciar el navegador únicamente","Compartir el caso públicamente en redes sociales"]'::jsonb, 1, 'Un comportamiento anómalo del asistente ante instrucciones ocultas debe reportarse y auditarse como posible intento de manipulación (prompt injection).'),
('ia_amenazas', '¿Cuál es una señal de alerta clave en un video ''oficial'' compartido por WhatsApp anunciando un cambio drástico y urgente en tu empresa?', '["Que use el logo correcto de la empresa","Que llegue por un canal no oficial y pida una acción inmediata sin posibilidad de verificación","Que dure menos de un minuto","Que tenga buena calidad de imagen"]'::jsonb, 1, 'Un canal no oficial combinado con urgencia y falta de vías de verificación es señal típica de contenido fraudulento, incluso si el video parece auténtico.'),
('canales_venta', 'Un cliente insiste en pagar por un enlace de pago que él mismo generó y te envía. ¿Qué es lo correcto?', '["Aceptarlo porque agiliza la venta","Rechazarlo y usar solo la pasarela de pago oficial de tu negocio","Aceptarlo solo si el cliente es frecuente","Pedir captura de pantalla del enlace antes de usarlo"]'::jsonb, 1, 'Enlaces de pago generados por terceros pueden ser fraudulentos o redirigir el dinero a otra cuenta; siempre usa tu propia pasarela oficial.'),
('canales_venta', '¿Qué medida reduce el riesgo de robo de datos en una tienda online construida en WooCommerce/WordPress?', '["Mantener el CMS, tema y plugins siempre actualizados","Usar contraseñas simples para recordarlas fácilmente","Desactivar los certificados SSL para mejorar la velocidad","Compartir el acceso de administrador con todo el equipo"]'::jsonb, 0, 'La mayoría de brechas en tiendas online explotan plugins o CMS desactualizados; mantenerlos al día es la defensa más efectiva.'),
('canales_venta', '¿Por qué es importante el certificado SSL (candado/HTTPS) en una tienda online?', '["Solo mejora el diseño visual del sitio","Cifra la comunicación entre el cliente y el servidor, protegiendo datos como tarjetas y contraseñas","Hace que la página cargue más lento","Es obligatorio solo para tiendas internacionales"]'::jsonb, 1, 'El SSL/HTTPS cifra los datos transmitidos, evitando que terceros intercepten información sensible como datos de pago.'),
('canales_venta', 'Un cliente pide que le envíes el número de cuenta bancaria por un chat público de Facebook para depositar. ¿Qué riesgo tiene?', '["Ninguno, es un canal oficial de la red social","Terceros que vean la publicación o chat filtrado podrían usar esos datos para estafar a otros clientes suplantando tu marca","Solo afecta si el monto es alto","Es más seguro que usar la pasarela de pago"]'::jsonb, 1, 'Publicar datos bancarios en canales no controlados facilita que estafadores los copien y los usen para suplantar tu negocio ante otros clientes.'),
('canales_venta', '¿Qué es un ataque de ''carding'' contra una tienda online?', '["Uso de tarjetas de crédito robadas para hacer compras de prueba y validar si funcionan","Un método de envío de mercadería","Un tipo de promoción de ventas","Un sistema de fidelización de clientes"]'::jsonb, 0, 'El carding usa la tienda para probar tarjetas robadas con compras pequeñas, generando contracargos y posibles sanciones a la tienda.'),
('canales_venta', '¿Qué práctica ayuda a prevenir el carding en una tienda online?', '["Permitir compras sin verificación de ningún tipo","Implementar verificación adicional (CVV, 3D Secure, límites de intentos fallidos)","Aceptar todas las tarjetas sin revisión","Eliminar el registro de pedidos"]'::jsonb, 1, 'Mecanismos como 3D Secure y límites de intentos dificultan que se prueben tarjetas robadas masivamente en la tienda.'),
('canales_venta', 'Un plugin desactualizado de tu tienda online tiene una vulnerabilidad conocida y pública. ¿Qué riesgo implica no actualizarlo?', '["Ninguno si la tienda tiene pocas visitas","Un atacante puede explotar la vulnerabilidad conocida para tomar control del sitio o robar datos","Solo afecta la velocidad de carga","Es un riesgo solo para tiendas internacionales"]'::jsonb, 1, 'Las vulnerabilidades públicas y conocidas son las primeras que buscan explotar los atacantes automatizados (bots de escaneo).'),
('canales_venta', '¿Cuál es un riesgo de usar el mismo usuario y contraseña de administrador en varias plataformas de venta (tienda, redes sociales, marketplace)?', '["Ninguno, facilita recordar las claves","Si una plataforma es vulnerada, el atacante puede acceder a todas las demás con la misma credencial","Mejora la seguridad general","Solo es riesgo para empresas grandes"]'::jsonb, 1, 'Reutilizar credenciales expande el impacto de una sola filtración a todos los canales de venta que comparten esa misma clave.'),
('canales_venta', 'Un cliente reclama que hizo un pago pero nunca llegó a la cuenta de tu negocio. ¿Qué es lo primero que debes verificar?', '["Que no haya usado un enlace de pago falso o cuenta bancaria incorrecta obtenida de un tercero","Ignorar el reclamo","Culpar directamente al banco sin revisar","Pedirle que pague de nuevo sin investigar"]'::jsonb, 0, 'Muchos casos de ''pago perdido'' se deben a que el cliente usó datos bancarios falsos obtenidos de una suplantación de tu marca.'),
('canales_venta', '¿Qué información NO debería mostrarse públicamente en el perfil de redes sociales de la tienda?', '["El horario de atención","Contraseñas o accesos administrativos de la plataforma","El catálogo de productos","La ubicación de la tienda"]'::jsonb, 1, 'Cualquier credencial o acceso administrativo debe mantenerse totalmente privado; publicarlo expone el negocio a un compromiso total.'),
('canales_venta', '¿Qué es el ''chargeback'' o contracargo en ventas online?', '["Una reversión del pago solicitada por el titular de la tarjeta ante el banco, a veces por fraude","Un descuento aplicado al cliente","Un tipo de publicidad pagada","Un método de envío gratuito"]'::jsonb, 0, 'El contracargo revierte un pago cuando el titular de la tarjeta reclama al banco, siendo frecuente en fraudes con tarjetas robadas.'),
('canales_venta', 'Un mensaje directo en Instagram ofrece ''verificar tu cuenta de negocio'' pidiendo tu contraseña. ¿Qué es esto?', '["Un servicio oficial de Instagram","Un intento de phishing para robar el control de tu cuenta comercial","Un requisito obligatorio anual","Una función de seguridad legítima"]'::jsonb, 1, 'Instagram no solicita contraseñas por mensaje directo; es una técnica común para robar cuentas comerciales con muchos seguidores.'),
('canales_venta', '¿Por qué es riesgoso dar acceso de administrador de la tienda online a un freelancer temporal sin control posterior?', '["No hay riesgo si el trabajo se hizo bien","Podría mantener acceso indebido después de terminar el contrato y comprometer la tienda","Es una práctica recomendada siempre","Mejora la seguridad del sitio"]'::jsonb, 1, 'Los accesos temporales deben revocarse al finalizar el contrato; dejarlos activos es una brecha de seguridad frecuente en MYPES.'),
('canales_venta', '¿Qué método de pago es más seguro recomendar en la tienda online frente a transferencias directas no verificadas?', '["Pasarelas de pago certificadas (ej. Culqi, Niubiz, PayPal) con protección al comprador y vendedor","Depósitos en efectivo a un tercero desconocido","Transferencias a cuentas personales sin registro","Pago contra cambio de dueño del negocio"]'::jsonb, 0, 'Las pasarelas certificadas cifran los datos de pago y ofrecen mecanismos de disputa y protección frente a fraudes.'),
('canales_venta', '¿Qué se recomienda antes de instalar un plugin nuevo en la tienda online?', '["Instalarlo de inmediato sin revisión","Verificar su reputación, actualizaciones recientes y valoraciones antes de instalarlo","Instalar la versión pirata para ahorrar costos","Ignorar las reseñas de otros usuarios"]'::jsonb, 1, 'Plugins sin soporte, mal valorados o pirateados suelen contener vulnerabilidades o código malicioso oculto.'),
('canales_venta', 'Un bot automatizado hace cientos de intentos de login al panel admin de tu tienda en minutos. ¿Qué tipo de ataque es?', '["Un ataque de fuerza bruta / credential stuffing","Una promoción automática","Un error del servidor","Una actualización del sistema"]'::jsonb, 0, 'Los ataques de fuerza bruta o relleno de credenciales prueban combinaciones de usuario/clave de forma automatizada hasta acceder.'),
('canales_venta', '¿Qué medida ayuda a frenar ataques de fuerza bruta al panel de administración de la tienda?', '["Permitir intentos ilimitados de login","Limitar intentos fallidos y activar 2FA en el acceso de administrador","Usar una contraseña de 4 dígitos","Publicar la URL del panel admin en redes sociales"]'::jsonb, 1, 'Limitar intentos y exigir un segundo factor de autenticación reduce drásticamente el éxito de ataques automatizados de fuerza bruta.'),
('canales_venta', '¿Qué riesgo tiene aceptar pagos por captura de pantalla de una transferencia sin verificar en el banco?', '["Ninguno, las capturas de pantalla no se pueden falsificar","Las capturas pueden ser editadas o falsificadas fácilmente para simular un pago que nunca se hizo","Es más seguro que verificar en el sistema bancario","Solo ocurre con montos grandes"]'::jsonb, 1, 'Las capturas de pantalla se editan fácilmente con apps de edición; el pago debe confirmarse directamente en el sistema bancario o pasarela.'),
('canales_venta', '¿Qué debes hacer si detectas actividad inusual (pedidos falsos masivos, cambios no autorizados) en tu tienda online?', '["Ignorarlo si no afecta las ventas del día","Cambiar contraseñas de administrador, revisar accesos recientes y contactar soporte técnico o hosting","Cerrar la tienda permanentemente sin investigar","Publicar las contraseñas nuevas en redes sociales para transparencia"]'::jsonb, 1, 'Ante actividad sospechosa se debe actuar rápido: cambiar credenciales, revisar accesos y buscar soporte técnico para contener el incidente.'),
('canales_venta', '¿Por qué no se recomienda compartir el acceso al panel de WhatsApp Business o redes sociales por WhatsApp personal sin control?', '["Porque no tiene ningún riesgo","Porque dificulta el control de quién accede y puede facilitar accesos indebidos o filtraciones","Porque WhatsApp lo prohíbe legalmente","Porque reduce las ventas"]'::jsonb, 1, 'Compartir accesos sin control ni registro dificulta saber quién hizo qué, complicando la respuesta ante un incidente de seguridad.'),
('canales_venta', 'Un cliente pide pagar por Yape/Plin a un número personal distinto al oficial de la empresa alegando ''promoción especial''. ¿Qué debes hacer?', '["Aceptar porque menciona una promoción","Verificar con tu negocio antes; nunca deben usarse cuentas personales no autorizadas para cobros oficiales","Aceptarlo sin preguntar si el monto es pequeño","Pedir que además pague por otro medio"]'::jsonb, 1, 'Los cobros deben canalizarse solo por cuentas oficiales autorizadas; solicitudes con cuentas distintas suelen ser intentos de fraude o desvío de fondos.'),
('canales_venta', '¿Qué rol cumple hacer copias de seguridad regulares de la tienda online (base de datos y archivos)?', '["Ninguno, el hosting siempre respalda todo automáticamente sin fallas","Permite recuperar la tienda rápidamente ante un hackeo, error o ransomware","Solo sirve para cumplir una formalidad","Aumenta el riesgo de fuga de datos"]'::jsonb, 1, 'Los respaldos regulares permiten restaurar la tienda tras un ataque, error humano o falla técnica, minimizando el tiempo de inactividad.'),
('canales_venta', '¿Qué es un ''skimmer digital'' (Magecart) en tiendas online?', '["Código malicioso insertado en la página de pago para robar datos de tarjetas en tiempo real","Un plugin de marketing","Un sistema de facturación electrónica","Una función de chat en vivo"]'::jsonb, 0, 'Los skimmers digitales insertan scripts maliciosos en el checkout que capturan datos de tarjeta mientras el cliente los ingresa, sin que se note.'),
('canales_venta', '¿Qué acción reduce el riesgo de un skimmer digital tipo Magecart en tu tienda?', '["No usar nunca pasarelas de pago","Mantener el CMS y extensiones actualizadas y monitorear cambios no autorizados en el código del checkout","Aceptar solo pagos en efectivo siempre","Eliminar la página de pago"]'::jsonb, 1, 'La actualización constante y el monitoreo de cambios en el checkout ayudan a detectar y prevenir la inserción de código malicioso.'),
('canales_venta', '¿Por qué es importante revisar los permisos de usuarios que administran el catálogo y pagos de la tienda?', '["No es importante si todos son de confianza","Aplicar mínimo privilegio evita que un usuario comprometido pueda modificar precios, pagos o robar datos de clientes","Solo es necesario en tiendas grandes","Reduce las ventas de la tienda"]'::jsonb, 1, 'Restringir permisos según la función de cada usuario limita el daño posible si una de esas cuentas es comprometida.'),
('contrasenas', '¿Cuál de estas combinaciones representa una contraseña más segura?', '["Peru2025","Nv#7kQ!x2pL@94","administrador","11111111"]'::jsonb, 1, 'Una contraseña segura mezcla mayúsculas, minúsculas, números y símbolos sin seguir un patrón predecible.'),
('contrasenas', '¿Qué es la autenticación de dos factores (2FA)?', '["Usar dos contraseñas iguales en dos sistemas","Un segundo paso de verificación además de la contraseña (ej. código al celular)","Cambiar la contraseña dos veces al año","Compartir la contraseña con dos personas"]'::jsonb, 1, 'El 2FA añade una verificación adicional (código, app autenticadora, biometría), protegiendo la cuenta aunque la contraseña sea robada.'),
('contrasenas', '¿Cuál es el riesgo principal de reutilizar la misma contraseña en varias cuentas?', '["Ninguno si la contraseña es larga","Si una cuenta es filtrada, todas las demás con la misma clave quedan expuestas","Mejora la seguridad general","Solo afecta cuentas personales, nunca laborales"]'::jsonb, 1, 'Una filtración en un solo servicio puede comprometer todas las cuentas donde se reutilizó la misma contraseña (''credential stuffing'').'),
('contrasenas', '¿Qué función cumple un gestor de contraseñas (ej. Bitwarden, 1Password)?', '["Generar y almacenar contraseñas únicas y complejas por cada cuenta de forma cifrada","Compartir automáticamente tus contraseñas en redes sociales","Eliminar la necesidad de tener contraseñas","Solo sirve para cuentas bancarias"]'::jsonb, 0, 'Un gestor de contraseñas genera claves únicas y fuertes para cada servicio, y las guarda cifradas, reduciendo el riesgo de reutilización.'),
('contrasenas', '¿Cuántos caracteres como mínimo se recomienda para una contraseña segura hoy en día?', '["4","6","12 o más","No importa la longitud"]'::jsonb, 2, 'Se recomienda un mínimo de 12 caracteres combinando tipos de caracteres, ya que contraseñas cortas se descifran en minutos con herramientas actuales.'),
('contrasenas', '¿Qué práctica de contraseñas debe evitarse en el entorno laboral?', '["Usar un gestor de contraseñas corporativo","Anotar las contraseñas en un post-it pegado al monitor","Activar 2FA en cuentas críticas","Cambiar contraseñas comprometidas de inmediato"]'::jsonb, 1, 'Anotar contraseñas visibles físicamente expone las credenciales a cualquier persona con acceso al espacio de trabajo.'),
('contrasenas', '¿Qué es un ataque de ''fuerza bruta'' contra una contraseña?', '["Un intento sistemático de probar múltiples combinaciones hasta acertar la contraseña correcta","Un tipo de virus para archivos PDF","Un método de respaldo en la nube","Una técnica de marketing digital"]'::jsonb, 0, 'La fuerza bruta prueba combinaciones automáticamente; contraseñas largas y complejas hacen este ataque impráctico por el tiempo que tomaría.'),
('contrasenas', '¿Por qué se recomienda cambiar la contraseña de una cuenta si aparece en una filtración de datos pública (data breach)?', '["No es necesario si la cuenta no se ha usado recientemente","Porque los atacantes prueban esas credenciales filtradas en otros servicios inmediatamente","Solo si el servicio lo exige por ley","Porque mejora la velocidad de la cuenta"]'::jsonb, 1, 'Las credenciales filtradas se venden y prueban automáticamente en otras plataformas; cambiarla de inmediato evita el acceso no autorizado.'),
('contrasenas', '¿Qué app de autenticación es un ejemplo de 2FA basado en ''algo que tienes''?', '["Google Authenticator o Microsoft Authenticator","Tu nombre de usuario","Tu fecha de nacimiento","El nombre de tu mascota"]'::jsonb, 0, 'Las apps autenticadoras generan códigos temporales únicos, representando el factor ''algo que tienes'' (el dispositivo con la app).'),
('contrasenas', '¿Qué se entiende por ''passphrase'' como alternativa a una contraseña compleja de símbolos?', '["Una frase larga y memorable combinando varias palabras poco relacionadas, más fácil de recordar y difícil de adivinar","Una sola palabra del diccionario","El nombre de la empresa seguido de un número","Una contraseña de 4 dígitos"]'::jsonb, 0, 'Una passphrase (ej. ''CaballoAzulLuna47!'') puede ser tan segura como una contraseña compleja pero más fácil de recordar.'),
('contrasenas', '¿Qué riesgo implica compartir la contraseña del correo corporativo con un compañero ''por si acaso''?', '["Ninguno si es de confianza","Pierde la trazabilidad de quién realizó cada acción y viola el principio de cuentas individuales","Mejora el trabajo en equipo sin riesgos","Es obligatorio para el trabajo colaborativo"]'::jsonb, 1, 'Compartir credenciales elimina la trazabilidad de acciones y dificulta identificar responsables ante un incidente de seguridad.'),
('contrasenas', '¿Cuál de estas NO es una buena práctica al crear una contraseña?', '["Usar el nombre de la empresa más el año actual","Combinar mayúsculas, minúsculas, números y símbolos","Usar una longitud de 12 caracteres o más","Usar un gestor de contraseñas para generarla"]'::jsonb, 0, 'Usar datos predecibles como el nombre de la empresa y el año es uno de los primeros patrones que prueban los atacantes.'),
('contrasenas', '¿Con qué frecuencia se recomienda cambiar contraseñas de cuentas críticas si no hay indicios de compromiso?', '["Nunca, si son suficientemente largas y únicas, y no hay señales de filtración","Cada día","Cada hora","Nunca es necesario revisar nada"]'::jsonb, 0, 'Las guías actuales priorizan contraseñas largas, únicas y 2FA sobre cambios forzados frecuentes, que suelen generar contraseñas más débiles y predecibles.'),
('contrasenas', '¿Qué es ''credential stuffing''?', '["Un ataque que prueba automáticamente combinaciones de usuario/contraseña filtradas en otros sitios para acceder a más cuentas","Un método de cifrado avanzado","Una técnica de respaldo de datos","Un tipo de firewall"]'::jsonb, 0, 'El credential stuffing reutiliza credenciales filtradas de otras plataformas para intentar acceder a cuentas donde se usó la misma clave.'),
('contrasenas', '¿Qué característica hace vulnerable a una contraseña como ''Contraseña123''?', '["Es demasiado larga","Sigue un patrón predecible y común, fácil de adivinar con diccionarios de contraseñas","Tiene mayúsculas","Tiene números"]'::jsonb, 1, 'Contraseñas basadas en palabras comunes seguidas de números son de las primeras que prueban los diccionarios de ataque.'),
('contrasenas', '¿Qué se debe hacer con las contraseñas por defecto de equipos nuevos (routers, cámaras, sistemas)?', '["Dejarlas como vienen de fábrica","Cambiarlas de inmediato por una contraseña única y fuerte","Compartirlas en el manual del equipo con el cliente","Usar la misma en todos los equipos de la empresa"]'::jsonb, 1, 'Las contraseñas de fábrica son públicas y conocidas por atacantes; deben cambiarse inmediatamente al configurar cualquier equipo.'),
('contrasenas', '¿Cuál es el mayor riesgo de guardar contraseñas en un archivo Excel sin cifrar en la computadora de trabajo?', '["Ninguno si el archivo tiene nombre discreto","Cualquiera con acceso al equipo o una filtración puede leer todas las contraseñas en texto plano","Mejora la organización sin riesgos","Es el método más seguro de gestión"]'::jsonb, 1, 'Un archivo sin cifrar expone todas las contraseñas juntas ante cualquier acceso no autorizado al equipo o backup.'),
('contrasenas', '¿Qué ventaja de seguridad ofrece el inicio de sesión biométrico (huella, rostro) combinado con contraseña?', '["Ninguna, es menos seguro que solo contraseña","Añade un factor adicional difícil de robar o replicar remotamente, reforzando el 2FA","Solo sirve para desbloquear el celular","Reemplaza la necesidad de proteger la cuenta"]'::jsonb, 1, 'La biometría añade un factor ''algo que eres'', complementando la contraseña y dificultando el acceso no autorizado remoto.'),
('contrasenas', 'Un empleado usa la contraseña de su Facebook personal también en el sistema de ventas de la empresa. ¿Qué riesgo genera?', '["Ninguno, son sistemas distintos y no se relacionan","Si Facebook sufre una filtración, esa misma clave podría usarse para acceder al sistema de ventas","Mejora la seguridad al usar una clave que ya recuerda","Es una práctica recomendada por expertos"]'::jsonb, 1, 'Reutilizar contraseñas entre cuentas personales y laborales expande el riesgo de cualquier filtración externa hacia sistemas críticos del negocio.'),
('contrasenas', '¿Qué es una ''contraseña maestra'' en un gestor de contraseñas?', '["La única contraseña que el usuario debe recordar para desbloquear el resto de sus claves guardadas y cifradas","Una contraseña compartida por todos los empleados","La contraseña del wifi de la oficina","Una clave que nunca cambia y es pública"]'::jsonb, 0, 'La contraseña maestra protege la bóveda cifrada del gestor; debe ser muy fuerte porque protege el acceso a todas las demás claves.'),
('contrasenas', '¿Qué se recomienda si sospechas que tu contraseña fue comprometida?', '["Esperar a ver si hay actividad extraña antes de actuar","Cambiarla de inmediato y revisar la actividad reciente de la cuenta","Compartirla con soporte técnico por chat","No hacer nada si la cuenta parece normal"]'::jsonb, 1, 'Ante sospecha de compromiso se debe actuar de inmediato: cambiar la clave y revisar accesos recientes para detectar actividad no autorizada.'),
('contrasenas', '¿Por qué usar preguntas de seguridad como ''¿nombre de tu mascota?'' puede ser riesgoso?', '["Porque son imposibles de responder","Porque suelen ser información que se puede encontrar en redes sociales del usuario","Porque cambian constantemente","Porque no las usa ningún sistema"]'::jsonb, 1, 'Muchas preguntas de seguridad son deducibles desde redes sociales públicas, debilitando esa capa de protección adicional.'),
('contrasenas', '¿Qué diferencia hay entre 2FA por SMS y 2FA por app autenticadora en términos de seguridad?', '["Son exactamente igual de seguros siempre","El SMS puede ser interceptado con ataques de SIM swapping; la app autenticadora es generalmente más segura","El SMS es más seguro en todos los casos","La app autenticadora no funciona sin internet nunca"]'::jsonb, 1, 'El SIM swapping permite a atacantes interceptar SMS de verificación; las apps autenticadoras no dependen de la red telefónica y son más resistentes.'),
('contrasenas', '¿Qué es el ''SIM swapping'' y cómo se relaciona con la seguridad de contraseñas y 2FA?', '["Un atacante transfiere tu número telefónico a otra SIM para interceptar códigos de verificación por SMS","Un tipo de contraseña compleja","Un método legítimo de respaldo telefónico","Una función de ahorro de batería"]'::jsonb, 0, 'El SIM swapping permite a un atacante recibir los SMS de verificación de la víctima, comprometiendo cuentas protegidas solo con 2FA por SMS.'),
('contrasenas', '¿Qué se debe hacer con las contraseñas de un sistema compartido (ej. caja registradora) cuando cambia el personal a cargo?', '["Mantenerla igual indefinidamente","Cambiarla cada vez que cambia el personal con acceso a esa cuenta","Compartirla verbalmente con todo el equipo","Escribirla en un cartel visible en el local"]'::jsonb, 1, 'Cambiar la contraseña ante rotación de personal evita que ex-empleados o personas no autorizadas mantengan acceso al sistema.'),
('accesos', '¿Qué significa el principio de ''mínimo privilegio'' en control de accesos?', '["Dar acceso total a todos para simplificar el trabajo","Otorgar a cada usuario solo los permisos estrictamente necesarios para su función","Que solo el administrador tenga acceso a todo el sistema","Que los permisos se asignan una sola vez y nunca cambian"]'::jsonb, 1, 'El mínimo privilegio limita el daño posible si una cuenta es comprometida, restringiendo el acceso solo a lo necesario para cada rol.'),
('accesos', 'Un vendedor requiere ver el catálogo y registrar ventas, pero no necesita acceso a la contabilidad general. ¿Qué debe hacerse?', '["Darle acceso total al sistema por comodidad","Configurar su perfil con permisos limitados solo a ventas y catálogo","No darle ningún acceso al sistema","Compartir la cuenta del administrador con él"]'::jsonb, 1, 'Los permisos deben ajustarse exactamente al rol del empleado, evitando accesos innecesarios a áreas sensibles como contabilidad.'),
('accesos', 'Un empleado renuncia y se va el mismo día. ¿Cuándo deben revocarse sus accesos a sistemas y correo?', '["Al final del mes","El mismo día de su salida","Cuando el nuevo empleado ingrese","Nunca es necesario si se fue en buenos términos"]'::jsonb, 1, 'Los accesos deben revocarse de inmediato el día de la salida; retrasar esto es una de las principales brechas de seguridad en empresas.'),
('accesos', '¿Qué riesgo implica que varios empleados usen la misma cuenta genérica (''ventas1'') para acceder al sistema?', '["Ninguno, ahorra tiempo en la gestión","Se pierde la trazabilidad de quién realizó cada acción específica","Mejora la seguridad al compartir responsabilidades","Es obligatorio por normativa"]'::jsonb, 1, 'Cuentas compartidas impiden identificar quién hizo qué acción, dificultando la auditoría e investigación ante cualquier incidente.'),
('accesos', '¿Qué es el control de acceso basado en roles (RBAC)?', '["Asignar permisos según el cargo o función del usuario dentro de la organización","Dar acceso aleatorio a los sistemas","Un tipo de antivirus","Un método de respaldo de datos"]'::jsonb, 0, 'RBAC agrupa permisos por rol (ej. vendedor, contador, admin), facilitando gestionar accesos de forma coherente y escalable.'),
('accesos', 'Un empleado de ventas pide temporalmente acceso a un módulo de administración para ''una tarea puntual''. ¿Qué es lo correcto?', '["Dar el acceso permanentemente por si se repite la necesidad","Otorgar el acceso solo por el tiempo necesario y revocarlo después de la tarea","Negar cualquier acceso sin excepción","Compartir la contraseña del administrador"]'::jsonb, 1, 'Los accesos temporales deben otorgarse solo por el periodo necesario y revocarse inmediatamente después, evitando privilegios acumulados innecesarios.'),
('accesos', '¿Por qué es riesgoso que el mismo usuario tenga permisos de ''crear'' y ''aprobar'' pagos en un sistema contable?', '["No hay riesgo si es una persona de confianza","Permite que una sola persona cometa fraude sin control cruzado (falta de segregación de funciones)","Mejora la velocidad de los pagos sin riesgos","Es un requisito legal obligatorio"]'::jsonb, 1, 'La segregación de funciones exige que crear y aprobar sean roles distintos, evitando que una sola persona controle todo el proceso sin supervisión.'),
('accesos', '¿Qué debe hacerse con los accesos de un empleado que cambia de área dentro de la misma empresa?', '["Mantener los accesos anteriores además de los nuevos","Revisar y ajustar sus permisos según su nuevo rol, retirando los que ya no correspondan","No hacer ningún cambio","Darle acceso de administrador por precaución"]'::jsonb, 1, 'Al cambiar de rol, los permisos deben actualizarse: agregar los nuevos necesarios y retirar los que ya no corresponden a su función anterior.'),
('accesos', '¿Qué es una auditoría periódica de accesos?', '["Revisar regularmente qué usuarios tienen qué permisos, para detectar accesos innecesarios o desactualizados","Un backup automático del sistema","Un cambio de contraseñas mensual obligatorio","Una capacitación de ventas"]'::jsonb, 0, 'Las auditorías de accesos detectan cuentas activas de ex-empleados, permisos excesivos o accesos que ya no son necesarios.'),
('accesos', '¿Por qué no se recomienda dar acceso de ''administrador'' por defecto a todos los empleados nuevos?', '["Porque es más rápido configurarlo así","Porque expone innecesariamente sistemas críticos a errores o compromisos de cuentas con bajo nivel de experiencia","Porque los empleados nuevos no saben usar computadoras","No hay ningún riesgo real"]'::jsonb, 1, 'Dar accesos de administrador sin necesidad amplía la superficie de riesgo; cualquier error o cuenta comprometida tendría impacto mayor.'),
('accesos', '¿Qué se debe verificar antes de otorgar acceso a un proveedor externo (ej. soporte técnico) a los sistemas de la empresa?', '["Nada, se le da acceso completo de inmediato para agilizar su trabajo","Que el acceso sea limitado a lo necesario, con fecha de expiración y trazabilidad de sus acciones","Que firme solo un contrato de confidencialidad, sin restringir accesos","Que use la misma cuenta que el administrador de la empresa"]'::jsonb, 1, 'Los accesos de terceros deben limitarse en alcance y tiempo, y quedar registrados para poder auditar sus acciones dentro del sistema.'),
('accesos', '¿Qué representa un mayor riesgo: un empleado activo con exceso de permisos, o un ex-empleado con accesos no revocados?', '["Solo el ex-empleado representa riesgo real","Ambos representan riesgos significativos de control de accesos que deben gestionarse activamente","Ninguno de los dos representa riesgo si la empresa es pequeña","Solo el empleado activo representa riesgo"]'::jsonb, 1, 'Tanto el exceso de privilegios como los accesos no revocados son fallas comunes de control de accesos que deben corregirse activamente.'),
('accesos', '¿Qué es la autenticación multifactor aplicada al control de accesos corporativos?', '["Exigir más de un factor de verificación (contraseña + código, biometría, etc.) para acceder a sistemas críticos","Usar la misma contraseña en varios sistemas","Un tipo de firewall de red","Un método de respaldo en la nube"]'::jsonb, 0, 'La autenticación multifactor añade capas de verificación, dificultando el acceso no autorizado aunque la contraseña sea comprometida.'),
('accesos', '¿Qué política de acceso es recomendable para sistemas críticos fuera del horario laboral?', '["Permitir acceso irrestricto las 24 horas sin monitoreo","Restringir o monitorear accesos fuera de horario habitual, alertando actividad inusual","Desactivar completamente el sistema fuera de horario sin excepciones","No es necesario ningún control adicional"]'::jsonb, 1, 'Monitorear o restringir accesos fuera de horario ayuda a detectar actividad sospechosa, ya que muchos ataques ocurren en horarios de baja vigilancia.'),
('accesos', '¿Qué es un ''log de accesos'' y por qué es importante mantenerlo?', '["Un registro de quién accedió a qué sistema y cuándo, útil para auditorías e investigación de incidentes","Un tipo de contraseña compleja","Un backup de archivos","Un plugin de la tienda online"]'::jsonb, 0, 'Los registros de acceso permiten reconstruir qué ocurrió ante un incidente y detectar patrones de acceso no autorizado.'),
('accesos', 'Un cliente interno solicita acceso ''solo para revisar'' un módulo sensible de recursos humanos. ¿Qué se debe evaluar antes de aprobar?', '["Aprobar de inmediato porque solo quiere ''revisar''","Si su rol realmente requiere ese acceso según el principio de mínimo privilegio","Dar acceso completo de administrador por si necesita más adelante","No es necesario evaluar nada"]'::jsonb, 1, 'Toda solicitud de acceso debe evaluarse contra la necesidad real del rol, sin asumir que ''solo revisar'' justifica un permiso amplio.'),
('accesos', '¿Qué riesgo genera no tener un proceso formal de onboarding/offboarding de accesos en la empresa?', '["Ninguno si la empresa es pequeña y todos se conocen","Accesos otorgados o revocados de forma inconsistente, generando brechas de seguridad","Mejora la flexibilidad del negocio sin riesgos","Es más eficiente no tener procesos formales"]'::jsonb, 1, 'Sin un proceso formal, es fácil olvidar revocar accesos de bajas o sobre-otorgar permisos a nuevos ingresos, generando brechas.'),
('accesos', '¿Por qué debe existir una cuenta de administrador distinta de la cuenta personal de trabajo diario, incluso para el dueño de la MYPE?', '["No es necesario, se puede usar la misma cuenta siempre para todo","Para reducir el uso innecesario de privilegios elevados en tareas rutinarias y limitar el impacto de un posible compromiso","Porque el sistema lo obliga sin razón técnica","Para tener más contraseñas que recordar sin beneficio real"]'::jsonb, 1, 'Usar una cuenta con privilegios elevados solo cuando es necesario reduce el riesgo de que una tarea rutinaria comprometa el sistema completo.'),
('accesos', '¿Qué se debe hacer si se detecta que un empleado accedió a información fuera del alcance de su rol sin autorización?', '["Ignorarlo si no causó daño visible","Investigar el caso, revisar permisos otorgados y corregir el acceso indebido","Darle acceso permanente ya que ''igual pudo entrar''","Compartir el hallazgo públicamente en redes sociales"]'::jsonb, 1, 'Todo acceso indebido detectado debe investigarse y corregirse de inmediato, ajustando los permisos según el principio de mínimo privilegio.'),
('accesos', '¿Qué ventaja tiene usar un sistema de gestión de identidades (IAM) incluso en una MYPE con pocos empleados?', '["Ninguna, es solo para empresas grandes","Centraliza y simplifica la gestión de accesos, altas, bajas y permisos de forma ordenada","Aumenta el costo sin ningún beneficio real","Reemplaza la necesidad de contraseñas"]'::jsonb, 1, 'Un sistema de gestión de identidades, aun simple, ordena qué usuario tiene qué acceso, facilitando auditorías y revocaciones rápidas.'),
('accesos', '¿Qué se recomienda hacer con cuentas de sistemas que llevan meses sin uso (empleados de vacaciones extendidas, licencias, etc.)?', '["Dejarlas activas indefinidamente sin revisión","Suspenderlas temporalmente y reactivarlas solo cuando la persona regrese","Eliminarlas permanentemente sin previo aviso","Compartirlas con otro empleado mientras tanto"]'::jsonb, 1, 'Suspender cuentas inactivas reduce la superficie de ataque; cuentas sin uso prolongado son un blanco atractivo si quedan activas sin monitoreo.'),
('accesos', '¿Qué es la ''separación de funciones'' (segregation of duties) en control de accesos?', '["Que ninguna persona tenga control total de un proceso crítico de principio a fin sin supervisión de otra","Que cada empleado trabaje en un escritorio distinto","Un tipo de firewall de red","Un backup diario automático"]'::jsonb, 0, 'Dividir tareas críticas (ej. quien registra el pago y quien lo aprueba) entre distintas personas previene fraude y errores no detectados.'),
('accesos', '¿Por qué revisar los permisos de acceso a la cuenta de correo corporativo compartida es importante en un negocio familiar (MYPE)?', '["No es importante entre familiares","Porque igual debe aplicarse el principio de mínimo privilegio y trazabilidad, incluso en relaciones de confianza","Porque las MYPES familiares no sufren ciberataques","Porque compartir todo sin control mejora la seguridad"]'::jsonb, 1, 'El control de accesos aplica independientemente de la relación personal entre los usuarios; la confianza no reemplaza buenas prácticas de seguridad.'),
('accesos', '¿Qué se debe hacer antes de otorgar acceso remoto (VPN, escritorio remoto) a un empleado que trabaja desde casa?', '["Otorgarlo sin ninguna configuración adicional de seguridad","Configurar autenticación fuerte (2FA), cifrado de la conexión y permisos limitados a lo necesario","Compartir la misma cuenta de acceso remoto entre varios empleados","Desactivar el antivirus para que la conexión sea más rápida"]'::jsonb, 1, 'El acceso remoto debe protegerse con autenticación fuerte y cifrado, ya que amplía la superficie de ataque fuera de la red controlada de la oficina.'),
('accesos', '¿Qué se debe verificar al revisar los permisos de una cuenta de servicio usada por un sistema automatizado (ej. backup automático, integración con pasarela de pago)?', '["No requiere revisión, las cuentas de servicio no representan riesgo","Que tenga solo los permisos estrictamente necesarios para su función automatizada y su credencial esté protegida","Que use la misma contraseña que la cuenta de administrador principal","Que esté visible públicamente para facilitar soporte técnico"]'::jsonb, 1, 'Las cuentas de servicio también deben regirse por mínimo privilegio y protección de credenciales, ya que un compromiso ahí puede afectar procesos automatizados críticos.'),
('ley_29733', '¿Qué exige la Ley N.° 29733 antes de recolectar datos personales de un cliente?', '["Nada, se pueden recolectar libremente","Informar la finalidad del tratamiento y obtener el consentimiento previo del titular","Solo registrar los datos en un cuaderno físico","Pagar una tarifa a INDECOPI por cada cliente"]'::jsonb, 1, 'La ley exige informar claramente para qué se usarán los datos y obtener el consentimiento del titular antes de recolectarlos.'),
('ley_29733', '¿Qué es el derecho ARCO reconocido por la Ley N.° 29733?', '["Acceso, Rectificación, Cancelación y Oposición sobre los datos personales","Un tipo de contraseña de acceso","Un sistema de facturación electrónica","Un protocolo de red segura"]'::jsonb, 0, 'El derecho ARCO permite al titular acceder, rectificar, cancelar u oponerse al tratamiento de sus datos personales.'),
('ley_29733', 'Un cliente solicita que elimines sus datos personales de tu sistema. ¿Qué debe hacer la empresa?', '["Ignorar la solicitud si sigue siendo cliente activo","Atender la solicitud dentro del plazo legal, salvo excepciones justificadas por ley","Pedir un pago para procesar la eliminación","Negarse siempre a eliminar cualquier dato"]'::jsonb, 1, 'El derecho de cancelación obliga a atender la solicitud del titular en el plazo legal, salvo obligaciones legales que impidan eliminarlos.'),
('ley_29733', '¿Qué autoridad supervisa el cumplimiento de la Ley N.° 29733 en Perú?', '["La Autoridad Nacional de Protección de Datos Personales (ANPD)","La SUNAT","El Ministerio de Trabajo","La Superintendencia de Banca y Seguros"]'::jsonb, 0, 'La Autoridad Nacional de Protección de Datos Personales es el ente encargado de supervisar y sancionar incumplimientos de la ley.'),
('ley_29733', '¿Es obligatorio registrar el banco de datos personales de una MYPE ante la autoridad competente?', '["Nunca es necesario para ninguna empresa","Sí, los bancos de datos personales deben registrarse ante la autoridad de protección de datos","Solo si la empresa tiene más de 500 empleados","Solo si la empresa es del sector financiero"]'::jsonb, 1, 'La ley exige el registro de los bancos de datos personales ante la autoridad correspondiente, independiente del tamaño de la empresa.'),
('ley_29733', '¿Qué debe incluir el consentimiento informado para el tratamiento de datos personales?', '["Solo la firma del cliente sin más detalle","Información clara sobre qué datos se recogen, con qué finalidad y a quién se transfieren si aplica","Un contrato de trabajo","El número de RUC de la empresa únicamente"]'::jsonb, 1, 'El consentimiento debe ser informado: el titular debe entender qué datos se usan, para qué y si serán compartidos con terceros.'),
('ley_29733', '¿Qué tipo de dato se considera ''sensible'' bajo la Ley N.° 29733?', '["El nombre y apellido del cliente","Datos de salud, orientación sexual, afiliación política o religiosa","El número de teléfono","La dirección de correo electrónico"]'::jsonb, 1, 'Los datos sensibles requieren protección reforzada por su naturaleza (salud, ideología, orientación, entre otros) y su tratamiento tiene reglas más estrictas.'),
('ley_29733', '¿Qué consecuencia puede tener para una MYPE no cumplir con la Ley N.° 29733?', '["Ninguna, la ley no aplica a pequeñas empresas","Sanciones económicas impuestas por la autoridad de protección de datos","Solo una advertencia verbal sin efectos legales","El cierre automático del negocio sin proceso previo"]'::jsonb, 1, 'El incumplimiento puede generar multas impuestas por la autoridad competente, proporcionales a la gravedad de la infracción.'),
('ley_29733', '¿Puede una empresa compartir la base de datos de clientes con un tercero (ej. otra empresa) sin consentimiento?', '["Sí, siempre que sea para fines comerciales propios","No, se requiere consentimiento del titular salvo excepciones legales específicas","Sí, si el tercero es un proveedor de confianza","Sí, sin ninguna restricción"]'::jsonb, 1, 'Transferir datos a terceros requiere consentimiento del titular, salvo las excepciones expresamente contempladas en la normativa.'),
('ley_29733', '¿Qué se entiende por ''finalidad del tratamiento'' de datos personales?', '["El propósito específico para el cual se recolectan y usan los datos, que debe ser informado al titular","El nombre del sistema informático usado","El precio del producto vendido","El horario de atención de la empresa"]'::jsonb, 0, 'La finalidad debe ser específica e informada; usar los datos para un fin distinto al comunicado infringe el principio de finalidad.'),
('ley_29733', 'Un negocio usa los correos de sus clientes (recolectados para enviar boletas) para enviarles publicidad sin avisarles. ¿Qué principio viola?', '["Ninguno, es una práctica normal de marketing","El principio de finalidad, al usar los datos para un propósito distinto al informado originalmente","El principio de gratuidad","No viola ningún principio si el negocio es pequeño"]'::jsonb, 1, 'Usar datos recolectados para un fin (boletas) en otro distinto (publicidad) sin nuevo consentimiento infringe el principio de finalidad de la ley.'),
('ley_29733', '¿Qué es el ''principio de proporcionalidad'' en la Ley N.° 29733?', '["Recolectar solo los datos personales estrictamente necesarios para la finalidad declarada","Recolectar la mayor cantidad de datos posible por si se necesitan después","Cobrar un precio proporcional al valor de los datos","Aplicar las mismas reglas a todas las empresas sin excepción"]'::jsonb, 0, 'El principio de proporcionalidad limita la recolección de datos a lo estrictamente necesario para la finalidad informada, evitando exceso de datos.'),
('ley_29733', '¿Durante cuánto tiempo debe conservarse la información personal de un cliente según la ley?', '["Indefinidamente sin ninguna restricción","Solo el tiempo necesario para cumplir la finalidad para la que fue recolectada, salvo obligación legal distinta","Siempre 100 años","Nunca debe conservarse ningún dato"]'::jsonb, 1, 'Los datos deben conservarse solo el tiempo necesario para la finalidad declarada o mientras exista una obligación legal que lo requiera.'),
('ley_29733', '¿Qué debe hacer una empresa si sufre una filtración de datos personales de sus clientes?', '["Ocultar el incidente para evitar mala reputación","Evaluar el impacto y, según corresponda, notificar a la autoridad y a los afectados","Esperar a que los clientes lo descubran por sí mismos","Cerrar el sistema definitivamente sin informar a nadie"]'::jsonb, 1, 'Ante una filtración, la empresa debe evaluar el riesgo y cumplir con las obligaciones de notificación según la normativa vigente.'),
('ley_29733', '¿El consentimiento para el tratamiento de datos personales puede ser retirado por el titular en cualquier momento?', '["No, una vez dado es irrevocable","Sí, el titular puede revocar su consentimiento en cualquier momento, salvo excepciones legales","Solo puede revocarse una vez al año","Solo si paga una tarifa administrativa"]'::jsonb, 1, 'El consentimiento es revocable en cualquier momento por el titular, salvo que exista una obligación legal que impida eliminar el tratamiento.'),
('ley_29733', '¿Qué rol cumple el ''encargado del tratamiento'' de datos personales frente al ''titular del banco de datos''?', '["Son lo mismo en todos los casos","El encargado trata los datos por cuenta del titular del banco de datos (ej. un proveedor de servicios), bajo sus instrucciones","El encargado siempre es el dueño legal de los datos","El encargado no tiene ninguna responsabilidad legal"]'::jsonb, 1, 'El encargado del tratamiento (ej. un proveedor externo de sistemas) procesa los datos siguiendo instrucciones del titular del banco de datos, y también tiene obligaciones legales.'),
('ley_29733', '¿Aplica la Ley N.° 29733 a los datos de los propios empleados de la empresa, no solo a los clientes?', '["No, solo protege datos de clientes externos","Sí, aplica también al tratamiento de datos personales de los trabajadores","Solo aplica a datos de proveedores","Solo aplica en empresas públicas"]'::jsonb, 1, 'La ley protege los datos personales de cualquier titular, incluyendo a los propios trabajadores de la empresa (planillas, contratos, etc.).'),
('ley_29733', '¿Qué medida de seguridad exige la ley de forma general para proteger los datos personales almacenados?', '["Ninguna medida técnica es obligatoria","Implementar medidas técnicas y organizativas adecuadas para evitar accesos no autorizados, pérdida o alteración","Solo se exige un contrato firmado en papel","Publicar los datos en un repositorio abierto"]'::jsonb, 1, 'La ley exige medidas de seguridad razonables (técnicas y organizativas) proporcionales al riesgo del tratamiento de datos personales.'),
('ley_29733', 'Un cliente pide corregir su nombre mal escrito en tu base de datos. ¿Qué derecho ARCO está ejerciendo?', '["Derecho de acceso","Derecho de rectificación","Derecho de cancelación","Derecho de oposición"]'::jsonb, 1, 'El derecho de rectificación permite corregir datos personales inexactos o desactualizados registrados por la empresa.'),
('ley_29733', '¿Puede un cliente oponerse a que sus datos se usen para publicidad, aunque haya dado consentimiento inicial para otro fin?', '["No, el consentimiento inicial cubre cualquier uso futuro","Sí, mediante el derecho de oposición reconocido en el derecho ARCO","Solo si paga una tarifa adicional","Solo si lo solicita por escrito notarial"]'::jsonb, 1, 'El derecho de oposición permite al titular rechazar usos específicos de sus datos, como fines publicitarios no autorizados expresamente.'),
('ley_29733', '¿Qué buena práctica ayuda a una MYPE a cumplir la Ley N.° 29733 en su día a día?', '["Recolectar datos de clientes sin ningún formulario de consentimiento","Tener una política de privacidad clara y visible, y solicitar consentimiento explícito al recolectar datos","Compartir libremente la base de datos con cualquier empresa aliada","Guardar los datos para siempre sin revisión"]'::jsonb, 1, 'Contar con una política de privacidad clara y solicitar consentimiento explícito es una práctica básica y accesible para cumplir la norma.'),
('ley_29733', '¿Qué pasa si una empresa recolecta datos de menores de edad sin autorización de sus padres o tutores?', '["No hay ninguna restricción especial para menores","Se infringe la protección reforzada que la ley otorga a los datos de menores de edad","Es una práctica permitida sin ninguna condición","Solo aplica si el menor tiene más de 16 años"]'::jsonb, 1, 'Los datos de menores de edad requieren protección reforzada y, en general, el consentimiento de los padres o tutores legales.'),
('ley_29733', '¿Es válido obtener el consentimiento para el tratamiento de datos mediante una casilla premarcada que el usuario debe desmarcar para negarse?', '["Sí, es la forma más eficiente y válida legalmente","No, el consentimiento debe ser una acción afirmativa y libre, no una omisión por defecto","Solo es válido si el texto está en letra pequeña","Depende únicamente del tamaño de la empresa"]'::jsonb, 1, 'El consentimiento debe darse mediante una acción afirmativa clara del titular; las casillas premarcadas no cumplen el estándar de consentimiento libre e informado.'),
('ley_29733', '¿Qué relación existe entre la Ley N.° 29733 y el manejo de datos sensibles de clientes que compran por la tienda online de una MYPE?', '["Ninguna, la ley solo aplica a bancos y aseguradoras","La ley aplica también a MYPES que procesan datos de clientes por canales digitales, incluyendo datos de pago y contacto","Solo aplica si la tienda tiene más de 10,000 visitas mensuales","Solo aplica a empresas extranjeras"]'::jsonb, 1, 'La Ley N.° 29733 aplica a cualquier empresa peruana, incluidas MYPES, que trate datos personales de clientes, sin importar el tamaño o canal de venta.'),
('ley_29733', '¿Qué debe hacer una MYPE si contrata un proveedor externo (ej. servicio de facturación en la nube) que tratará datos personales de sus clientes?', '["No es necesario ningún acuerdo, basta con contratar el servicio","Establecer un acuerdo o cláusula de encargo de tratamiento que defina las obligaciones del proveedor sobre esos datos","Dejar que el proveedor use los datos como desee","Solo es necesario si el proveedor es extranjero"]'::jsonb, 1, 'Cuando un tercero trata datos personales por cuenta de la empresa, debe formalizarse su rol como encargado de tratamiento, con obligaciones claras de protección de datos.'),
('datos_sensibles', 'Un cliente envía el número completo de su tarjeta por WhatsApp para una compra. ¿Cuál es la acción correcta?', '["Guardarlo en el celular para futuras compras","Procesarlo únicamente por una plataforma de pago certificada y no almacenarlo fuera de ella","Anotarlo en un cuaderno de ventas","Reenviarlo al área de cobranzas por correo"]'::jsonb, 1, 'Los datos de tarjetas solo deben procesarse en plataformas certificadas (PCI-DSS); almacenarlos en chats o documentos expone a fraude y sanciones.'),
('datos_sensibles', '¿Cuál es la forma correcta de desechar documentos físicos con datos personales de clientes (contratos, boletas con DNI)?', '["Tirarlos directamente al tacho de basura","Triturarlos o usar un servicio certificado de destrucción documental","Guardarlos indefinidamente en el almacén sin control","Reciclarlos como papel normal sin destruir la información"]'::jsonb, 1, 'Los documentos con datos personales deben destruirse de forma segura para evitar que terceros accedan a información confidencial descartada.'),
('datos_sensibles', '¿Qué es la ''minimización de datos'' aplicada al manejo de información sensible?', '["Recolectar todos los datos posibles del cliente por si se necesitan después","Recolectar y conservar solo los datos estrictamente necesarios para la finalidad del negocio","Reducir el tamaño de los archivos digitales","Usar contraseñas más cortas"]'::jsonb, 1, 'La minimización reduce el riesgo al limitar qué datos se recolectan y almacenan, evitando exponer información innecesaria en caso de una brecha.'),
('datos_sensibles', '¿Qué riesgo implica guardar contraseñas y datos de tarjetas de clientes en una hoja de Excel compartida en la nube sin cifrar?', '["Ninguno si solo el equipo de ventas tiene el enlace","Exposición de datos sensibles ante cualquier filtración de acceso al archivo o enlace compartido","Mejora la organización del equipo sin riesgos","Es un método recomendado por auditores"]'::jsonb, 1, 'Un archivo sin cifrado ni control de acceso adecuado puede filtrarse fácilmente, exponiendo datos financieros sensibles de los clientes.'),
('datos_sensibles', '¿Qué estándar internacional regula específicamente el manejo seguro de datos de tarjetas de pago?', '["ISO 9001","PCI-DSS (Payment Card Industry Data Security Standard)","Ley de Contrataciones del Estado","Reglamento de Tránsito"]'::jsonb, 1, 'PCI-DSS establece los requisitos de seguridad que deben cumplir las empresas que procesan, almacenan o transmiten datos de tarjetas de pago.'),
('datos_sensibles', 'Un empleado necesita compartir el DNI de un cliente con otro colaborador para una gestión interna. ¿Cuál es la forma más segura?', '["Enviarlo por un grupo abierto de WhatsApp del área","Usar un canal interno autorizado y limitar el acceso solo a quien lo necesita para esa gestión específica","Publicarlo en un tablero físico de la oficina","Enviarlo por correo personal del empleado"]'::jsonb, 1, 'Compartir datos sensibles debe hacerse por canales controlados y solo con quien realmente necesita esa información para su tarea (mínimo privilegio).'),
('datos_sensibles', '¿Qué se entiende por ''dato sensible'' además de los datos financieros, según buenas prácticas de manejo de información?', '["El nombre comercial de la empresa","Datos de salud, biométricos o de menores de edad, que requieren protección reforzada","El horario de atención al público","El precio de los productos en catálogo"]'::jsonb, 1, 'Datos de salud, biométricos y de menores requieren un nivel de protección mayor por el impacto que tendría su exposición indebida.'),
('datos_sensibles', '¿Qué práctica ayuda a proteger datos sensibles almacenados en la computadora de la empresa?', '["Dejar la sesión de Windows sin contraseña para acceso rápido","Cifrar el disco duro y usar contraseña de inicio de sesión en el equipo","Compartir la PC con todo el personal sin restricciones","Guardar los datos en el escritorio sin ninguna carpeta protegida"]'::jsonb, 1, 'El cifrado de disco y la protección con contraseña evitan que datos sensibles sean accesibles si el equipo es robado o extraviado.'),
('datos_sensibles', '¿Qué se debe hacer antes de desechar o vender una computadora antigua que almacenó datos de clientes?', '["Solo borrar los archivos de la papelera de reciclaje","Realizar un borrado seguro o destrucción física del disco para evitar recuperación de datos","Formatear una vez con formato rápido y venderla de inmediato","No es necesario ningún paso adicional"]'::jsonb, 1, 'El borrado seguro (wipe) o destrucción del disco evita que datos eliminados de forma simple sean recuperados por el nuevo propietario del equipo.'),
('datos_sensibles', 'Un cliente reclama que sus datos personales fueron usados sin su consentimiento en una campaña de marketing. ¿Qué se debe evaluar primero?', '["Ignorar el reclamo si el cliente sigue comprando","Si existió consentimiento informado para ese uso específico de los datos","Culpar al proveedor de marketing sin revisar el caso","Ofrecer un descuento sin resolver el problema de fondo"]'::jsonb, 1, 'Debe verificarse si hubo consentimiento explícito para ese uso específico; sin eso, se infringe el principio de finalidad de los datos.'),
('datos_sensibles', '¿Qué medida reduce el riesgo de que un dato sensible se filtre por error humano (ej. enviar a la persona equivocada)?', '["No usar correo electrónico nunca","Verificar destinatarios antes de enviar y limitar el uso de copia oculta cuando corresponda","Enviar la información a varios contactos para asegurarse de que llegue","Escribir los datos sensibles en el asunto del correo"]'::jsonb, 1, 'Verificar cuidadosamente los destinatarios antes de enviar información sensible previene una de las causas más comunes de filtración de datos.'),
('datos_sensibles', '¿Qué se recomienda hacer con los datos de clientes que ya no son necesarios para el negocio (ej. clientes inactivos hace años)?', '["Conservarlos indefinidamente sin ninguna revisión","Evaluar su eliminación o anonimización si ya no hay finalidad ni obligación legal para conservarlos","Venderlos a otra empresa sin consentimiento","Publicarlos como parte de un reporte público"]'::jsonb, 1, 'Datos sin finalidad vigente ni obligación legal de conservación deben eliminarse o anonimizarse, reduciendo el riesgo de exposición innecesaria.'),
('datos_sensibles', '¿Qué riesgo implica imprimir reportes con datos sensibles de clientes y dejarlos en la impresora compartida?', '["Ninguno si la oficina es pequeña","Cualquier persona con acceso a la impresora puede ver información confidencial de clientes","Mejora el tiempo de respuesta del área","Es una práctica recomendada de transparencia"]'::jsonb, 1, 'Documentos sensibles olvidados en impresoras compartidas exponen información confidencial a cualquier persona que pase por el área.'),
('datos_sensibles', '¿Qué es la anonimización de datos y para qué se usa en el manejo de información sensible?', '["Eliminar información que permita identificar a una persona específica, manteniendo su utilidad estadística","Cambiar el nombre de la empresa en los reportes","Cifrar únicamente las contraseñas del sistema","Un tipo de firewall de red"]'::jsonb, 0, 'La anonimización elimina identificadores personales de los datos, permitiendo analizarlos (ej. para reportes) sin exponer la identidad de las personas.'),
('datos_sensibles', '¿Por qué no se recomienda enviar datos sensibles de clientes a herramientas de IA generativa pública sin verificar su política de datos?', '["Porque las herramientas de IA nunca aceptan texto en español","Porque esos datos podrían almacenarse o usarse fuera del control de la empresa, violando la confidencialidad","Porque no es posible copiar y pegar texto en esas herramientas","No hay ningún riesgo real"]'::jsonb, 1, 'Sin verificar la política de privacidad de la herramienta de IA, los datos sensibles ingresados podrían quedar expuestos o ser reutilizados indebidamente.'),
('datos_sensibles', '¿Qué se debe hacer si se detecta que un archivo con datos sensibles de clientes fue enviado por error a un destinatario equivocado?', '["No hacer nada si el destinatario no responde","Solicitar la eliminación del archivo, evaluar el impacto y, si corresponde, notificar según la normativa","Esperar a que el cliente afectado lo descubra por sí mismo","Culpar al sistema de correo sin tomar acción"]'::jsonb, 1, 'Ante un envío erróneo de datos sensibles se debe actuar rápido: pedir eliminación, evaluar impacto y cumplir las obligaciones de notificación si aplica.'),
('datos_sensibles', '¿Qué rol cumple el cifrado en el manejo de datos sensibles almacenados o transmitidos?', '["Ninguno, solo afecta la velocidad de los sistemas","Convierte la información en un formato ilegible sin la clave correcta, protegiéndola ante accesos no autorizados","Solo es útil para el correo electrónico","Reemplaza la necesidad de contraseñas"]'::jsonb, 1, 'El cifrado protege los datos aunque sean interceptados o robados, ya que sin la clave correspondiente resultan ilegibles para terceros.'),
('datos_sensibles', '¿Qué práctica de manejo de datos sensibles aplica al usar USB o discos externos con información de clientes?', '["Usarlos sin cifrado y compartirlos libremente entre empleados","Cifrar el dispositivo y limitar su uso solo a personal autorizado con control de dónde se lleva","Dejarlos siempre conectados a la computadora principal","No es necesario ningún control especial"]'::jsonb, 1, 'Los dispositivos externos con datos sensibles deben cifrarse y su uso debe limitarse, ya que son fáciles de perder o robar.'),
('datos_sensibles', '¿Qué se debe considerar antes de contratar un servicio en la nube (ej. hosting, CRM) que almacenará datos sensibles de clientes peruanos?', '["Solo el precio del servicio","Las medidas de seguridad del proveedor y si cumple con obligaciones aplicables de protección de datos","El diseño de la interfaz del servicio","Si el proveedor tiene oficinas físicas en Perú únicamente"]'::jsonb, 1, 'Antes de delegar el almacenamiento de datos sensibles a un tercero, deben evaluarse sus garantías de seguridad y cumplimiento normativo.'),
('datos_sensibles', '¿Por qué compartir capturas de pantalla de conversaciones con datos de clientes en redes sociales internas o grupos de trabajo es riesgoso?', '["No es riesgoso si el grupo es privado","Puede exponer datos personales o financieros del cliente a personas que no deberían tener acceso a ellos","Mejora la comunicación del equipo sin ningún riesgo","Es una práctica exigida por buenas prácticas de atención al cliente"]'::jsonb, 1, 'Compartir capturas con datos de clientes expande el acceso a información sensible más allá de quienes realmente la necesitan, aumentando el riesgo de filtración.'),
('datos_sensibles', '¿Qué es el ''principio de confidencialidad'' aplicado al tratamiento de datos sensibles en la empresa?', '["Que todos los empleados puedan ver todos los datos de todos los clientes","Que solo el personal autorizado según su rol pueda acceder a información sensible","Que los datos se compartan libremente con proveedores externos","Que los datos se publiquen para mayor transparencia"]'::jsonb, 1, 'La confidencialidad exige restringir el acceso a datos sensibles solo al personal que efectivamente lo necesita para su función.'),
('datos_sensibles', 'Un empleado toma una foto de un documento con datos de un cliente usando su celular personal para ''agilizar el trámite''. ¿Qué riesgo genera?', '["Ninguno si borra la foto después","El dato queda fuera del control de la empresa, en un dispositivo personal sin las mismas protecciones","Mejora la eficiencia sin ningún riesgo","Es una práctica recomendada para todos los trámites"]'::jsonb, 1, 'Usar dispositivos personales para manejar datos sensibles saca la información del control y las medidas de seguridad corporativas, aumentando el riesgo de filtración.'),
('datos_sensibles', '¿Qué se debe hacer con los correos electrónicos antiguos que contienen datos sensibles de clientes y ya no tienen utilidad para el negocio?', '["Conservarlos indefinidamente en la bandeja de entrada","Evaluar su archivado seguro o eliminación conforme a la política de retención de datos de la empresa","Reenviarlos a todo el equipo para que los revisen","Publicarlos en un documento compartido abierto"]'::jsonb, 1, 'Aplicar una política de retención de datos evita acumular información sensible sin necesidad, reduciendo la superficie de exposición ante una filtración.'),
('datos_sensibles', '¿Qué relación hay entre el manejo de datos sensibles y el control de accesos dentro de la empresa?', '["Ninguna relación, son temas totalmente independientes","El control de accesos es la principal barrera técnica para limitar quién puede ver o modificar datos sensibles","El control de accesos solo aplica a sistemas financieros","Los datos sensibles no requieren ningún tipo de control de acceso"]'::jsonb, 1, 'Un buen control de accesos (mínimo privilegio, roles definidos) es la base técnica para proteger efectivamente los datos sensibles de la empresa.'),
('datos_sensibles', 'Un cliente pide por teléfono que le ''confirmes'' el número de tarjeta que tienen registrado de él. ¿Qué debes hacer?', '["Leerle el número completo para confirmar","Nunca leer datos completos de tarjeta por teléfono; verificar identidad por otros medios y usar sistemas seguros","Pedirle que adivine los últimos dígitos","Enviarle el dato por SMS de inmediato"]'::jsonb, 1, 'Confirmar datos de tarjeta por teléfono expone información sensible a posible ingeniería social; deben usarse canales y procesos verificados que no revelen el dato completo.'),
('resiliencia', '¿Qué establece la regla de respaldo ''3-2-1''?', '["3 copias en el mismo disco, 2 veces al día, 1 responsable","3 copias de los datos, en 2 medios distintos, con 1 copia fuera de la oficina","3 contraseñas, 2 factores, 1 usuario","3 respaldos anuales, 2 revisiones, 1 proveedor"]'::jsonb, 1, 'La regla 3-2-1 garantiza recuperación ante fallos de hardware, robo o ransomware al diversificar dónde y cómo se guardan las copias de seguridad.'),
('resiliencia', 'Tu empresa sufre un ataque de ransomware que cifra todos los archivos. ¿Cuál es la primera acción correcta?', '["Pagar el rescate de inmediato para recuperar los archivos","Aislar los equipos afectados de la red y evaluar restaurar desde un respaldo limpio","Intentar descifrar los archivos con programas gratuitos de internet","Reiniciar la computadora repetidamente hasta que funcione"]'::jsonb, 1, 'Aislar los equipos evita que el ransomware se propague; luego se restaura desde un respaldo limpio y se reporta el incidente.'),
('resiliencia', '¿Por qué no se recomienda pagar el rescate exigido en un ataque de ransomware?', '["Porque es ilegal en todos los casos sin excepción","Porque no garantiza recuperar los archivos y financia futuras actividades criminales","Porque los atacantes nunca piden dinero, solo datos","Porque los archivos se recuperan solos después de pagar"]'::jsonb, 1, 'Pagar no asegura la recuperación de los datos y perpetúa el modelo de negocio de los atacantes, incentivando más ataques.'),
('resiliencia', '¿Con qué frecuencia se recomienda probar que los respaldos (backups) realmente se puedan restaurar?', '["Nunca, basta con que se generen automáticamente","Periódicamente, verificando que la restauración funcione correctamente","Solo una vez al momento de configurarlos","Cada 5 años"]'::jsonb, 1, 'Un respaldo que nunca se prueba puede fallar al momento de restaurarlo; probarlo periódicamente asegura que realmente sirva en una emergencia.'),
('resiliencia', '¿Qué es un plan de continuidad del negocio (business continuity plan) básico para una MYPE?', '["Un documento que define cómo seguir operando ante incidentes como fallas técnicas, ciberataques o desastres","Un plan de marketing anual","Un contrato con un proveedor de internet","Un manual de atención al cliente"]'::jsonb, 0, 'El plan de continuidad define acciones concretas para mantener operaciones críticas del negocio ante interrupciones inesperadas.'),
('resiliencia', '¿Qué riesgo implica guardar el único respaldo de los archivos de la empresa en el mismo disco duro de la computadora principal?', '["Ninguno, es la forma más práctica de respaldar","Si ese disco falla, se pierde tanto el original como el respaldo al mismo tiempo","Mejora la velocidad de acceso a los datos","Es la recomendación estándar de seguridad"]'::jsonb, 1, 'Un respaldo en el mismo disco no protege ante fallas de hardware, robo o ransomware que afecten a ese dispositivo completo.'),
('resiliencia', '¿Qué acción es prioritaria para reducir el impacto de una falla eléctrica repentina en los equipos de la empresa?', '["No hacer nada, es un riesgo poco frecuente","Usar un UPS (batería de respaldo) para apagar los equipos de forma segura","Dejar los equipos encendidos permanentemente sin protección","Comprar más computadoras de repuesto"]'::jsonb, 1, 'Un UPS protege contra apagones repentinos, permitiendo un apagado seguro que evita pérdida o corrupción de datos.'),
('resiliencia', '¿Qué se debe hacer si el proveedor principal de un servicio crítico (ej. hosting de la tienda online) sufre una caída prolongada?', '["Esperar indefinidamente sin ningún plan alterno","Tener identificado un proveedor o plan de contingencia alterno para minimizar el tiempo de inactividad","Cerrar el negocio hasta que el proveedor resuelva el problema","Culpar públicamente al proveedor sin buscar alternativas"]'::jsonb, 1, 'Contar con un plan de contingencia (proveedor alterno, respaldo de datos accesible) reduce el impacto de fallas de terceros críticos para el negocio.'),
('resiliencia', '¿Qué es un ''punto único de falla'' (single point of failure) en la operación de una MYPE?', '["Un elemento (persona, sistema o equipo) cuya falla detiene por completo la operación del negocio","Un tipo de virus informático","Un método de cifrado de archivos","Un plugin de seguridad para tiendas online"]'::jsonb, 0, 'Identificar puntos únicos de falla (ej. solo una persona sabe usar el sistema, un solo servidor sin respaldo) permite mitigarlos antes de que ocurra un incidente.'),
('resiliencia', '¿Por qué es riesgoso que solo una persona en la empresa sepa administrar los sistemas críticos (contraseñas, accesos, backups)?', '["No hay ningún riesgo si esa persona es de confianza","Si esa persona no está disponible (renuncia, enfermedad), la empresa puede quedar sin control de sus propios sistemas","Mejora la seguridad al concentrar el conocimiento en una sola persona","Es la práctica recomendada para empresas pequeñas"]'::jsonb, 1, 'Concentrar todo el conocimiento crítico en una sola persona genera un punto único de falla; se recomienda documentar y compartir procesos clave con más de una persona de confianza.'),
('resiliencia', '¿Qué información mínima debería documentarse para poder recuperar la operación tras un incidente grave?', '["Ninguna, se puede improvisar en el momento","Inventario de sistemas críticos, contactos de proveedores clave y ubicación de respaldos","Solo el número de teléfono del dueño del negocio","El catálogo de productos de la tienda"]'::jsonb, 1, 'Documentar sistemas críticos, contactos y ubicación de respaldos permite actuar rápido y ordenado durante una crisis, en vez de improvisar.'),
('resiliencia', '¿Qué diferencia hay entre un respaldo ''en la nube'' y un respaldo ''local'' dentro de la regla 3-2-1?', '["No hay ninguna diferencia relevante","Son dos medios distintos que se complementan, protegiendo ante distintos tipos de riesgo (robo físico, fallas de conexión, etc.)","El respaldo local siempre es innecesario si hay nube","El respaldo en la nube nunca debe usarse por seguridad"]'::jsonb, 1, 'Combinar nube y almacenamiento local diversifica el riesgo: la nube protege ante robo/incendio local, y el respaldo local protege ante fallas de conectividad o del proveedor cloud.'),
('resiliencia', '¿Qué se recomienda hacer con los respaldos que se guardan ''fuera de la oficina'' según la regla 3-2-1?', '["Guardarlos en el mismo edificio en otro piso solamente","Ubicarlos en una localización físicamente distinta (nube u otro local) para proteger ante incendios, robos o desastres locales","No es necesario que estén fuera de la oficina","Guardarlos únicamente en el celular personal de un empleado"]'::jsonb, 1, 'Un respaldo fuera del sitio protege específicamente ante eventos que afecten físicamente a la oficina, como incendios, inundaciones o robos.'),
('resiliencia', '¿Qué acción ayuda a que una MYPE se recupere más rápido tras un ciberataque, incluso con recursos limitados?', '["No tener ningún plan y resolver todo de forma improvisada","Tener respaldos probados, contactos clave documentados y roles claros de quién hace qué ante una crisis","Depender únicamente de que el seguro cubra todo el daño","Esperar a que el problema se resuelva solo con el tiempo"]'::jsonb, 1, 'La preparación previa (respaldos probados, roles definidos, contactos clave) es la diferencia clave entre una recuperación rápida y una crisis prolongada.'),
('resiliencia', '¿Por qué se recomienda mantener el software y sistema operativo de los equipos actualizados como parte de la resiliencia?', '["Porque las actualizaciones nunca corrigen fallas de seguridad","Porque muchas actualizaciones corrigen vulnerabilidades que los atacantes explotan activamente","Porque hace que los equipos funcionen más lento intencionalmente","No tiene relación con la resiliencia del negocio"]'::jsonb, 1, 'Las actualizaciones suelen incluir parches de seguridad para vulnerabilidades conocidas; no aplicarlas deja puertas abiertas a ataques evitables.'),
('resiliencia', '¿Qué se debe hacer si se detecta actividad sospechosa (archivos cifrados, procesos desconocidos) en un equipo de la empresa?', '["Seguir usando el equipo normalmente","Desconectarlo de la red inmediatamente y evitar seguir usándolo hasta evaluar el incidente","Reiniciarlo varias veces seguidas sin desconectarlo","Compartir el equipo con otros para verificar si les pasa lo mismo"]'::jsonb, 1, 'Aislar el equipo sospechoso de la red de inmediato evita que una posible infección (ej. ransomware) se propague a otros sistemas.'),
('resiliencia', '¿Qué rol cumple un seguro de ciberriesgo (cyber insurance) dentro de la resiliencia de una MYPE?', '["Reemplaza la necesidad de tener respaldos y buenas prácticas de seguridad","Puede ayudar a cubrir costos económicos de un incidente, pero no reemplaza medidas preventivas como respaldos y capacitación","No existe ese tipo de seguro para empresas pequeñas","Solo cubre daños físicos a los equipos"]'::jsonb, 1, 'El seguro de ciberriesgo complementa, pero no sustituye, las medidas preventivas técnicas y de capacitación necesarias para reducir el impacto de un incidente.'),
('resiliencia', '¿Qué se recomienda hacer con los respaldos una vez restaurado un sistema tras un ataque de ransomware?', '["Reconectar todo de inmediato sin verificar nada más","Verificar que el respaldo restaurado esté limpio de malware antes de reconectar todos los sistemas a la red","Eliminar el respaldo usado inmediatamente después de restaurarlo","Ignorar cualquier verificación adicional"]'::jsonb, 1, 'Antes de reconectar sistemas restaurados, debe verificarse que el respaldo usado esté realmente limpio, evitando reinfectar la red nuevamente.'),
('resiliencia', '¿Qué significa tener ''tiempo de recuperación objetivo'' (RTO) definido para los sistemas críticos de la empresa?', '["El tiempo máximo aceptable que un sistema puede estar caído antes de que el negocio sufra un impacto grave","El tiempo que tarda un empleado en llegar a la oficina","El tiempo de garantía de un equipo nuevo","El tiempo que dura una capacitación de seguridad"]'::jsonb, 0, 'Definir un RTO ayuda a priorizar qué sistemas deben recuperarse primero y con qué urgencia ante una interrupción, orientando el plan de continuidad.'),
('resiliencia', '¿Por qué probar simulacros de incidentes (ej. simular una caída de sistema o un ataque) es útil incluso para una MYPE pequeña?', '["No aporta ningún valor si el negocio es pequeño","Permite identificar fallas en el plan de respuesta antes de que ocurra un incidente real","Solo sirve para grandes corporaciones con muchos empleados","Genera pérdidas económicas sin ningún beneficio"]'::jsonb, 1, 'Los simulacros revelan huecos en el plan de continuidad (quién no sabe qué hacer, qué contacto falta) antes de que un incidente real los exponga.'),
('resiliencia', '¿Qué se recomienda respecto a los respaldos automáticos configurados en la nube (ej. Google Drive, OneDrive)?', '["Confiar en que sincronizan todo perfectamente sin revisión alguna","Verificar periódicamente que efectivamente están respaldando los archivos críticos y no solo una carpeta parcial","Desactivarlos porque siempre fallan","Usarlos como único respaldo sin ninguna copia adicional"]'::jsonb, 1, 'Los respaldos automáticos deben verificarse periódicamente para asegurar que cubren realmente los archivos críticos del negocio, no solo una parte de ellos.'),
('resiliencia', '¿Qué relación existe entre la resiliencia del negocio y la capacitación constante del personal en ciberseguridad?', '["Ninguna relación, son temas separados","Un personal capacitado reacciona mejor y más rápido ante incidentes, reduciendo el impacto y tiempo de recuperación","La capacitación solo sirve para el área de sistemas","La resiliencia depende únicamente de la tecnología, no de las personas"]'::jsonb, 1, 'La resiliencia combina tecnología (respaldos, planes) con personas capacitadas que sepan reconocer y reaccionar ante incidentes rápidamente.'),
('resiliencia', '¿Qué se debe hacer con los proveedores críticos (ej. hosting, pasarela de pago) en un plan de resiliencia?', '["No es necesario documentarlos ni tener alternativas","Identificarlos, documentar sus contactos de soporte y evaluar alternativas ante una posible falla prolongada","Confiar en que nunca fallarán","Cambiar de proveedor cada mes por precaución"]'::jsonb, 1, 'Conocer a los proveedores críticos y tener alternativas evaluadas reduce el tiempo de inactividad si alguno falla o deja de dar servicio.'),
('resiliencia', '¿Cuál es un beneficio clave de la resiliencia con recursos mínimos para una MYPE peruana?', '["Requiere inversiones millonarias imposibles para una MYPE","Permite mantener la continuidad del negocio con medidas simples y de bajo costo (backups, UPS, capacitación) adaptadas a su realidad","Solo aplica a empresas con presupuesto de ciberseguridad dedicado","Elimina por completo cualquier riesgo de incidente"]'::jsonb, 1, 'La resiliencia con recursos mínimos busca medidas prácticas y accesibles (respaldos, UPS, capacitación) que una MYPE puede implementar sin grandes inversiones.'),
('resiliencia', '¿Qué se recomienda hacer con los manuales o procedimientos de recuperación ante incidentes en una MYPE?', '["No documentarlos, basta con la experiencia informal del dueño","Mantenerlos escritos, accesibles y actualizados para que más de una persona pueda ejecutarlos en una emergencia","Guardarlos únicamente en la memoria de un solo empleado clave","Cambiarlos completamente cada semana sin necesidad"]'::jsonb, 1, 'Procedimientos documentados y accesibles evitan depender de una sola persona y permiten actuar con rapidez y orden ante un incidente real.');
